class Solution {
public:
    vector<int> fairCandySwap(vector<int>& aliceSizes, vector<int>& bobSizes) {
        long long sumA = 0, sumB = 0;
        for (int x : aliceSizes) sumA += x;
        for (int x : bobSizes) sumB += x;
        long long delta = (sumB - sumA) / 2;
        unordered_set<int> bob_set(bobSizes.begin(), bobSizes.end());
        for (int x : aliceSizes) {
            if (bob_set.count(x + delta)) {
                return {x, (int)(x + delta)};
            }
        }
        return {};
    }
};

class Solution {
    public int[] fairCandySwap(int[] aliceSizes, int[] bobSizes) {
        int sumA = 0, sumB = 0;
        for (int x : aliceSizes) sumA += x;
        for (int x : bobSizes) sumB += x;
        int delta = (sumB - sumA) / 2;
        Set<Integer> bobSet = new HashSet<>();
        for (int x : bobSizes) bobSet.add(x);
        for (int x : aliceSizes) {
            if (bobSet.contains(x + delta)) {
                return new int[]{x, x + delta};
            }
        }
        return new int[0];
    }
}

var fairCandySwap = function(aliceSizes, bobSizes) {
    const sumA = aliceSizes.reduce((a, b) => a + b, 0);
    const sumB = bobSizes.reduce((a, b) => a + b, 0);
    const delta = (sumB - sumA) / 2;
    const bobSet = new Set(bobSizes);
    for (const x of aliceSizes) {
        if (bobSet.has(x + delta)) {
            return [x, x + delta];
        }
    }
    return [];
};
